import org.springframework.web.bind.annotation.*;
import org.springframework.http.HttpStatus;
import java.util.*;

@RestController                 // @Controller + @ResponseBody for all methods
@RequestMapping("/api/tasks")
public class TaskController {

    private final TaskService taskService;  // injected dependency

    // Constructor injection -- recommended over field injection
    public TaskController(TaskService taskService) {
        this.taskService = taskService;
    }

    @GetMapping                       // GET /api/tasks
    public List<Task> getAllTasks() {
        return taskService.findAll();  // serialized to JSON by Jackson
    }

    @GetMapping("/{id}")              // GET /api/tasks/{id}
    public Task getTask(@PathVariable Long id) {
        return taskService.findById(id);
    }

    @PostMapping                      // POST /api/tasks
    @ResponseStatus(HttpStatus.CREATED)
    public Task createTask(@RequestBody Task task) {
        return taskService.save(task);  // @RequestBody deserializes JSON to Task
    }

    @DeleteMapping("/{id}")           // DELETE /api/tasks/{id}
    @ResponseStatus(HttpStatus.NO_CONTENT)
    public void deleteTask(@PathVariable Long id) {
        taskService.deleteById(id);
    }
}

@RestController
@RequestMapping("/api/orders")
public class OrderController {  // Controller layer
    private final OrderService orderService;

    public OrderController(OrderService orderService) {
        this.orderService = orderService;
    }

    @GetMapping("/{id}")
    public ResponseEntity<OrderResponse> getOrder(@PathVariable Long id) {
        var order = orderService.findById(id);  // Delegates to service
        return ResponseEntity.ok(new OrderResponse(order));
    }
}

@Service
public class OrderService {  // Model layer - business logic
    private final OrderRepository repository;

    public Order findById(Long id) {
        return repository.findById(id)
            .orElseThrow(() -> new OrderNotFoundException(id));
    }
}

record OrderResponse(Long id, String item, BigDecimal price) {  // View layer representation
    OrderResponse(Order order) {
        this(order.getId(), order.getItem(), order.getPrice());
    }
}

