@RestController
@RequestMapping("/api/orders")
public class OrderController {  // Only HTTP concerns
    private final OrderService orderService;

    @PostMapping
    public ResponseEntity<OrderResponse> createOrder(@RequestBody OrderRequest request) {
        var order = orderService.createOrder(request.toOrder());  // Delegate to service
        return ResponseEntity.status(HttpStatus.CREATED)
            .body(new OrderResponse(order));
    }
}

@Service
public class OrderService {  // Business logic only
    private final OrderRepository repository;
    private final InventoryService inventoryService;

    @Transactional
    public Order createOrder(Order order) {
        if (order.getTotal().compareTo(BigDecimal.ZERO) <= 0) {
            throw new InvalidOrderException("Order total must be positive");
        }
        inventoryService.reserveItems(order.getItems());  // Business workflow
        return repository.save(order);
    }
}

@Repository
interface OrderRepository extends JpaRepository<Order, Long> {  // Data access only
    List<Order> findByCustomerId(Long customerId);
}

@RestController
@RequestMapping("/api/customers")  // Class-level base path
public class CustomerController {
    private final CustomerService customerService;

    @GetMapping  // Maps GET /api/customers
    public List<CustomerResponse> getAllCustomers() {
        return customerService.findAll().stream()
            .map(CustomerResponse::new)
            .toList();
    }

    @GetMapping("/{id}")  // Maps GET /api/customers/{id}
    public ResponseEntity<CustomerResponse> getCustomer(@PathVariable Long id) {
        var customer = customerService.findById(id);
        return ResponseEntity.ok(new CustomerResponse(customer));
    }

    @PostMapping  // Maps POST /api/customers
    public ResponseEntity<CustomerResponse> createCustomer(@RequestBody CustomerRequest request) {
        var customer = customerService.create(request.toCustomer());
        return ResponseEntity.status(HttpStatus.CREATED)
            .body(new CustomerResponse(customer));
    }

    @DeleteMapping("/{id}")  // Maps DELETE /api/customers/{id}
    public ResponseEntity<Void> deleteCustomer(@PathVariable Long id) {
        customerService.delete(id);
        return ResponseEntity.noContent().build();
    }
}

