@Controller
public class MixedController {
    @GetMapping("/page")
    public String htmlPage() { return "view"; } // HTML

    @GetMapping("/data")
    @ResponseBody // Makes this method return JSON instead of view
    public User jsonData() { return new User(1L, "Bob"); }
}
